import { clamp01 } from '../core/contracts.js';
export function makeEventSignature(input={}){return Object.freeze({eventId:input.eventId||null,eventType:input.eventType||null,season:input.season||null,region:input.region||null,numeric:Object.fromEntries(Object.entries(input.numeric||{}).filter(([,v])=>Number.isFinite(v)).map(([k,v])=>[k,Number(v)])),categorical:Object.fromEntries(Object.entries(input.categorical||{}).filter(([,v])=>v!==null&&v!==undefined).map(([k,v])=>[k,String(v)])),observedAt:input.observedAt||null});}
export function signatureDistance(a,b,{scales={}}={}){if(a.eventType&&b.eventType&&a.eventType!==b.eventType)return{comparable:false,distance:Infinity,common:0};let sum=0,n=0;for(const k of Object.keys(a.numeric||{})){if(!Number.isFinite(b.numeric?.[k]))continue;const scale=Math.max(1e-9,Number(scales[k])||1);const d=(a.numeric[k]-b.numeric[k])/scale;sum+=d*d;n++;}for(const k of Object.keys(a.categorical||{})){if(b.categorical?.[k]===undefined)continue;sum+=a.categorical[k]===b.categorical[k]?0:1;n++;}return{comparable:n>=2,distance:n?Math.sqrt(sum/n):Infinity,common:n};}
